     5	export function validateWav(bytes: Uint8Array, maxSeconds = 60) {
     6	    const invalid = () => new ApiError(400, 'Send a valid PCM WAV recording of 60 seconds or less.');
     7	    if (bytes.length < 44)
     8	        throw invalid();
     9	    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    10	    const text = (offset: number) => new TextDecoder().decode(bytes.subarray(offset, offset + 4));
    11	    if (text(0) !== 'RIFF' || text(8) !== 'WAVE' || view.getUint32(4, true) + 8 !== bytes.length)
    12	        throw invalid();
    13	    let byteRate = 0, blockAlign = 0, dataSize = 0, hasData = false;
    14	    let offset = 12;
    15	    const dataChunks: number[] = [];
    16	    for (; offset + 8 <= bytes.length;) {
    17	        const size = view.getUint32(offset + 4, true), start = offset + 8;
    18	        if (start + size > bytes.length)
    19	            throw invalid();
    20	        if (text(offset) === 'fmt ') {
    21	            if (size < 16 || view.getUint16(start, true) !== 1)
    22	                throw invalid();
    23	            const channels = view.getUint16(start + 2, true), rate = view.getUint32(start + 4, true), bits = view.getUint16(start + 14, true);
    24	            byteRate = view.getUint32(start + 8, true);
    25	            blockAlign = view.getUint16(start + 12, true);
    26	            if (![1, 2].includes(channels) || rate < 8000 || rate > 48000 || ![16, 24, 32].includes(bits) || blockAlign !== channels * bits / 8 || byteRate !== rate * blockAlign)
    27	                throw invalid();
    28	        }
    29	        if (text(offset) === 'data') {
    30	            dataSize += size;
    31	            hasData = true;
    32	            dataChunks.push(size);
    33	        }
    34	        offset = start + size + (size % 2);
    35	    }
    36	    if (offset !== bytes.length || !hasData || !byteRate || !dataSize || dataChunks.some(size => size % blockAlign !== 0) || dataSize / byteRate > maxSeconds)
    37	        throw invalid();
    38	}
