    61	    const chunks: Uint8Array[] = [];
    62	    let length = 0;
    63	    while (true) {
    64	        const { done, value } = await reader.read();
    65	        if (done)
    66	            break;
    67	        length += value.length;
    68	        if (length > max) {
    69	            await reader.cancel();
