    71	        }
    72	        chunks.push(value);
    73	    }
    74	    const bytes = new Uint8Array(length);
    75	    let offset = 0;
    76	    for (const chunk of chunks) {
    77	        bytes.set(chunk, offset);
    78	        offset += chunk.length;
    79	    }
    80	    return bytes;
    81	}
