   126	function finalizeStreamingWav(source: Uint8Array) {
   127	    // Gradium streams WAV with unknown RIFF/data sizes. Finalize only these
   128	    // sentinel fields after the bounded response ends; validate everything next.
   129	    const bytes = source.slice();
