   133	    const tag = (offset: number) => new TextDecoder().decode(bytes.subarray(offset, offset + 4));
   134	    if (tag(0) !== 'RIFF' || tag(8) !== 'WAVE')
   135	        return bytes;
   136	    if (view.getUint32(4, true) === 0xffffffff)
   137	        view.setUint32(4, bytes.length - 8, true);
   138	    for (let offset = 12; offset + 8 <= bytes.length;) {
   139	        const size = view.getUint32(offset + 4, true);
   140	        if (tag(offset) === 'data' && size === 0xffffffff) {
   141	            view.setUint32(offset + 4, bytes.length - offset - 8, true);
   142	            break;
   143	        }
   144	        offset += 8 + size + (size % 2);
   145	    }
   146	    return bytes;
   147	}
